/* 報告共用元件：減重報告與健檢報告共用的排版、判讀標準與上傳擷取。
   工作台先載入 lab/lab.js 與這個檔，再分別載入減重（weight/）與健檢（checkup/），兩邊互不依賴。
   只放「與哪一位病人、哪一個畫面無關」的東西；讀取畫面欄位的函式留在各自的程式裡。 */
/* ---------- 診所 logo（報告封面與頁首） ---------- */
const CLINIC_LOGO_DATA_URI = 'data:image/png;base64,';
/* ---------- 外部程式庫 ---------- */
// 外部程式庫用到時才載入（上傳檢驗 PDF、匯出 PDF 報告），開頁不必等它們。
// 開頁幾秒後再於背景預先載入，離線快取也會一併存下，斷網時仍可使用。
const LIBS = {
  pdfjs:       'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js',
  html2canvas: 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js',
  jspdf:       'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js'
};
const libLoading = {};
function loadLib(name){
  if(!libLoading[name]) libLoading[name] = new Promise((ok, bad)=>{
    const s = document.createElement('script');
    s.src = LIBS[name];
    s.onload = ok;
    s.onerror = ()=>{ delete libLoading[name]; s.remove(); bad(new Error(name + ' 載入失敗')); };
    document.head.appendChild(s);
  });
  return libLoading[name];
}
async function ensurePdfjs(){
  try{
    await loadLib('pdfjs');
    pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
  }catch(e){ console.warn('pdf.js 載入失敗，PDF預覽功能將無法使用', e); }
}
// 開頁幾秒後在背景預先載入
setTimeout(()=>{
  ensurePdfjs();
  loadLib('html2canvas').catch(()=>{});
  loadLib('jspdf').catch(()=>{});
}, 4000);
/* ---------- 輸入合理範圍（減重欄位檢查與 TANITA 擷取共用） ---------- */
